import { useEffect, useState } from 'react';
import { GetProps, Image } from 'antd';
import AhAntdConfig from '../utils/AhAntdConfig';
import { IFileObjVoBase } from '@allahjs/utils';

type ImageProps = GetProps<typeof Image>;
export const defImgUrl =
  'data:image/png;base64,';

/**
 * 异步图片渲染组件
 */
const AhImageRender = ({
  cosKey,
  fileId,
  imageProps,
  width,
  height,
  preview,
  request
}: {
  cosKey?: string;
  fileId?: string;
  imageProps: ImageProps;
  width?: number;
  height?: number;
  preview?: boolean;
  request?: () => Promise<IFileObjVoBase[]> | string;
}) => {
  const uploadConfig = AhAntdConfig.getUploadConfig();

  const [url, setUrl] = useState<string>();

  const isVideo = /\.(mp4|avi|mov|wmv|flv|mkv|webm|m4v|3gp)(\?.*)?$/i.test(url || '');

  useEffect(() => {
    init();
  }, [fileId]);

  const init = async () => {
    // 如果两个配置都没有就报错
    if (!uploadConfig.getSignUrlByFileId || !uploadConfig.getSigUrlByKey) {
      console.error('无效的配置信息，请补充getSignUrlByFileId或getSigUrlByKey');
      return;
    }

    // 检查 request 是否存在
    if (request) {
      const res = await request(); // 执行 request
      if (typeof res === 'string') {
        setUrl(res);
      } else {
        setUrl(res?.[0]?.preview);
      }
      return;
    }

    // 原有逻辑
    if (uploadConfig.getSigUrlByKey && cosKey) {
      const res = await uploadConfig.getSigUrlByKey(cosKey);
      setUrl(res);
      return;
    }
    if (uploadConfig.getSignUrlByFileId && fileId) {
      const res = await uploadConfig.getSignUrlByFileId(fileId);
      setUrl(res);
    }
  };

  if (isVideo) {
    return (
      <video
        src={url}
        controls
        style={{
          width,
          height,
          display: 'block'
        }}
      />
    );
  }

  return (
    <Image
      src={url}
      preview={preview || true}
      fallback={defImgUrl}
      alt=""
      width={width}
      height={height}
      {...imageProps}
    />
  );
};
export default AhImageRender;
